  {
    path: paths.app.root.path,
    lazy: () => import('./routes/app/root'),
    children: [
      { path: paths.app.discussions.path, lazy: () => import('./routes/app/discussions') },
      { path: paths.app.discussion.path, lazy: () => import('./routes/app/discussion') },
    ],
  },
]);

